{"statements": [
  {
    "id": "3.1.1a",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"Do not pass\")",
    "text": "a driver SHOULD NOT pass a vehicle WHEN the vehicle is stopped at a crosswalk BECAUSE a stopped vehicle may be a clue that a pedestrian is crossing",
    "sources": [
      {"id": "m76", "quote": "Do not pass a vehicle stopped at a crosswalk. A stopped vehicle may be a clue that a pedestrian is crossing."}
    ],
    "flags": [],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.4a",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "text (\"can use\")",
    "text": "a cyclist MAY use any part of the lane WHEN it is [?necessary for safety]",
    "sources": [
      {"id": "m54", "quote": "However, they can use any part of the lane if necessary for safety, such as to:"},
      {"id": "m55", "quote": "Discourage passing where the lane is too narrow to be shared safely"}
    ],
    "flags": [
      {"code": "J", "span": "necessary for safety", "note": "No objective test for when lane usage is necessary."}
    ],
    "links": [],
    "note": "The list of purposes in m54 includes \"Discourage passing where the lane is too narrow to be shared safely\" (m55), which is the passing-related item cited here."
  },
  {
    "id": "3.4.4b",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "text (\"must maintain\")",
    "text": "a driver of a motor vehicle MUST maintain a minimum distance of 1 m between the vehicle and the cyclist WHILE passing the cyclist [?where practical] IF VIOLATED a fine AND 2 demerit points",
    "sources": [
      {"id": "m56", "quote": "When passing a cyclist, drivers of motor vehicles must maintain a minimum distance of one metre, where practical between their vehicle and the cyclist."},
      {"id": "m57", "quote": "(See Diagram 2-11.) Failure to do so may result in a fine and an additional two demerit points on the driver's record."},
      {"id": "m59", "quote": "bike lane adjacent to parking bays"}
    ],
    "flags": [
      {"code": "J", "span": "where practical", "note": "No criterion for when maintaining 1 m is not practical."}
    ],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.4c",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "text (\"should\")",
    "text": "a driver SHOULD change lanes to pass a cyclist WHEN [?whenever possible]",
    "sources": [
      {"id": "m58", "quote": "Whenever possible, you should change lanes to pass."}
    ],
    "flags": [
      {"code": "J", "span": "whenever possible", "note": "No criterion for when changing lanes is possible."}
    ],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.4d",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"Do not sound\")",
    "text": "a driver SHOULD NOT sound the horn [?unnecessarily] WHILE overtaking a cyclist BECAUSE it may frighten the cyclist and cause the cyclist to lose control",
    "sources": [
      {"id": "m60", "quote": "Do not sound your horn unnecessarily when you are overtaking a cyclist. It may frighten them and cause them to lose control."}
    ],
    "flags": [
      {"code": "J", "span": "unnecessarily", "note": "No criterion for what use of the horn is necessary."}
    ],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.4e",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"tap\")",
    "text": "a driver SHOULD tap the horn quickly and lightly WHEN the driver uses the horn WHILE overtaking a cyclist AND the driver is still [?some distance] away from the cyclist",
    "sources": [
      {"id": "m60", "quote": "If you feel that you must use your horn, tap it quickly and lightly while you are still some distance away from the cyclist."}
    ],
    "flags": [
      {"code": "J", "span": "some distance", "note": "No specific distance given."}
    ],
    "links": [],
    "note": "The \"must\" in the source is a personal feeling, not a legal obligation; the force comes from the bare imperative \"tap\"."
  },
  {
    "id": "3.4.4f",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"look\", \"check\")",
    "text": "a driver SHOULD look behind AND check the mirrors and blind spots for a passing cyclist WHEN the driver is parked on the side of the roadway AND the driver is about to open a door",
    "sources": [
      {"id": "m96", "quote": "When parked on the side of the roadway, look behind you and check your mirrors and blind spots for a passing cyclist before opening a door."}
    ],
    "flags": [],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.6a",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"do not cut\")",
    "text": "a driver SHOULD NOT cut in front [?closely] of a large vehicle WHILE passing the vehicle BECAUSE it reduces the space cushion large vehicles require to stop [?safely]",
    "sources": [
      {"id": "m65", "quote": "When passing a large vehicle, do not cut in front closely. Not only is this discourteous, it is dangerous; it reduces the space cushion large vehicles require in order to stop safely."}
    ],
    "flags": [
      {"code": "J", "span": "closely", "note": "No measure of how close is too close."},
      {"code": "J", "span": "safely", "note": "No measure of safe stopping distance for large vehicles."}
    ],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.6b",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"Allow\")",
    "text": "a driver SHOULD allow [?more room] WHEN passing a large vehicle",
    "sources": [
      {"id": "m65", "quote": "Allow more room when passing a large vehicle."}
    ],
    "flags": [
      {"code": "J", "span": "more room", "note": "No specific amount of extra space."}
    ],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.6c",
    "type": "FACT",
    "force": null,
    "force_from": null,
    "text": "FACT a large vehicle can create heavy air turbulence that may affect the driver's ability to control the vehicle WHILE passing the large vehicle",
    "sources": [
      {"id": "m66", "quote": "6. Turbulence - Due to various factors such as air pressure and airflow, a large vehicle can create heavy air turbulence. This may affect your ability to control your vehicle when passing a large one."}
    ],
    "flags": [],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.7a",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"Stay\")",
    "text": "a driver SHOULD stay [?well back] from farm machinery",
    "sources": [
      {"id": "m69", "quote": "Stay well back and do not pass until it is safe to do so."}
    ],
    "flags": [
      {"code": "J", "span": "well back", "note": "No specific following distance."}
    ],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.7b",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"do not pass\")",
    "text": "a driver SHOULD NOT pass farm machinery UNTIL it is [?safe] to do so",
    "sources": [
      {"id": "m69", "quote": "Stay well back and do not pass until it is safe to do so."}
    ],
    "flags": [
      {"code": "J", "span": "safe", "note": "No observable test for safety when passing farm machinery."}
    ],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.8a",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"Maintain\")",
    "text": "a driver SHOULD maintain a [?safe] following distance from a horse-drawn vehicle",
    "sources": [
      {"id": "m70", "quote": "Maintain a safe following distance and only pass when it is safe to do so."}
    ],
    "flags": [
      {"code": "J", "span": "safe", "note": "No specific following distance."}
    ],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.8b",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"pass\")",
    "text": "a driver SHOULD pass a horse-drawn vehicle ONLY IF it is [?safe] to do so",
    "sources": [
      {"id": "m70", "quote": "Maintain a safe following distance and only pass when it is safe to do so."}
    ],
    "flags": [
      {"code": "J", "span": "safe", "note": "No observable test for safety when passing a horse-drawn vehicle."}
    ],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.8c",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"give\")",
    "text": "a driver SHOULD give [?as much distance as possible] between the vehicle and the horse-drawn vehicle WHILE passing it BECAUSE passing [?too closely] could scare or startle the horse, causing it to change direction suddenly on the roadway",
    "sources": [
      {"id": "m71", "quote": "When passing, give as much distance between you and them as possible. Passing too closely could scare or startle the horse, causing it to change direction suddenly on the roadway."}
    ],
    "flags": [
      {"code": "J", "span": "as much distance as possible", "note": "No specific passing distance."},
      {"code": "J", "span": "too closely", "note": "No specific passing distance."}
    ],
    "links": [],
    "note": null
  }
]}
